import sys
sys.path.insert(0, ".")
from text import slugify
cases = {"What?": "what", "C++ is fun!": "c-is-fun", "Hello (World)": "hello-world",
         "Wow!!! Great...": "wow-great", '"Quoted" text': "quoted-text", "50% off!": "50-off",
         "Rock & Roll": "rock-roll", "Hi, there; friend:": "hi-there-friend", "#tag @user": "tag-user"}
for s, exp in cases.items():
    if slugify(s) != exp:
        sys.exit(1)
sys.exit(0)

