import sys, re
sys.path.insert(0, ".")
from text import slugify
def orig(s):
    return re.sub(r'\s+', '-', s.strip().lower())
for s in ["Hello World", "  Multiple   Spaces here ", "ABC", "tab\tsep", "a b c 1 2", "Python 3 Rocks", "simple", "MiXeD CaSe 42"]:
    if slugify(s) != orig(s):
        sys.exit(1)
sys.exit(0)
